package dev.cardadvisor.finance;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.context.annotation.Import;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"codef.config-file=","codef.storage-key-file=","openai.config-file=","account.mail-config-file="})
@Import(FinancialConnectionsPostgresTest.LocalProviderConfiguration.class)
@EnabledIfEnvironmentVariable(named="RUN_DEVICE_FREE_ANDROID_TEST",matches="true")
class AndroidSyncAuthenticationPostgresTest{
 @LocalServerPort int port;@Autowired JdbcTemplate db;@Autowired FinancialConnectionsPostgresTest.Stub provider;
 String adb(String...args)throws Exception{var c=new ArrayList<String>(List.of(System.getenv("LOCALAPPDATA")+"/Android/Sdk/platform-tools/adb.exe","-s","emulator-5554"));c.addAll(List.of(args));var p=new ProcessBuilder(c).redirectErrorStream(true).start();var read=CompletableFuture.supplyAsync(()->{try{return new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "";}});if(!p.waitFor(120,TimeUnit.SECONDS)){p.destroyForcibly();fail("Synthetic Android timeout");}assertEquals(0,p.exitValue());return read.get(3,TimeUnit.SECONDS);}
 @Test void twoRoundsOfAuthenticationImportExactlyOnce()throws Exception{
  String run=UUID.randomUUID().toString();provider.calls.clear();provider.behaviors.clear();provider.behaviors.add(new FinancialConnectionsPostgresTest.Behavior());
  for(String method:List.of("smsAuthNo","simpleAuth")){var b=new FinancialConnectionsPostgresTest.Behavior();b.code="CF-03002";b.approvalData=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("method",method).put("jobIndex",0).put("threadIndex",0).put("jti","SYNTHETIC_AUTH_JTI").put("twoWayTimestamp",System.currentTimeMillis());provider.behaviors.add(b);}
  var result=new FinancialConnectionsPostgresTest.Behavior();result.approvalData=CodefApprovalNormalizerTest.row("UIAUTH1","50000","0","");provider.behaviors.add(result);var report=new LinkedHashMap<String,Object>();report.put("passed",false);report.put("physicalDevice",false);report.put("actualProviderCalls",0);
  try{adb("reverse","tcp:18080","tcp:"+port);String output=adb("shell","am","instrument","-w","-r","-e","class","dev.cardadvisor.android.SyncAuthenticationFlowTest","-e","runId",run,"dev.cardadvisor.android.test/androidx.test.runner.AndroidJUnitRunner");report.put("failureLocations",java.util.regex.Pattern.compile("SyncAuthenticationFlowTest\\.kt:[0-9]+").matcher(output).results().map(java.util.regex.MatchResult::group).distinct().toList());assertTrue(output.contains("OK (1 test)"),"Synthetic authentication UI failed; raw output withheld");UUID user=db.queryForObject("SELECT id FROM app_users WHERE email=?",UUID.class,"sync-auth-ui-"+run+"@example.test");assertEquals(1,db.queryForObject("SELECT count(*) FROM ledger_entries WHERE user_id=?",Integer.class,user));assertEquals(1,db.queryForObject("SELECT count(*) FROM financial_sync_runs WHERE user_id=? AND status='IMPORTED'",Integer.class,user));assertNull(db.queryForObject("SELECT ciphertext FROM financial_sync_auth WHERE user_id=?",byte[].class,user));assertEquals(4,provider.calls.size());report.put("passed",true);
  }finally{db.update("DELETE FROM app_users WHERE email=?","sync-auth-ui-"+run+"@example.test");adb("reverse","--remove","tcp:18080");Files.writeString(Path.of("../.run/sync-auth-android.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(report));}
 }
}
